-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
hl.monitor({
    output   = "",
    mode     = "1920x1200@60",
    position = "auto",
    scale    = "1",
})



hl.env("GDK_WAYLAND_DISABLE", "ext_background_effect_manager_v1")

