-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/
hl.config({
    general = {
        gaps_in          = 6,
        gaps_out         = 8,

        border_size      = 2,

        col              = {
            active_border   = { colors = { "#128fc9", "#10c787" }, angle = 45 },
            inactive_border = "rgba(595959aa)",
        },

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = true,

        -- Please see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/ before you turn this on
        allow_tearing    = false,

        layout           = "dwindle",
    },

    decoration = {
        rounding         = 12,
        -- rounding_power   = 28,

        -- Change transparency of focused and unfocused windows
        active_opacity   = 1.0,
        inactive_opacity = 1.0,

        shadow           = {
            enabled      = true,
            range        = 4,
            render_power = 3,
            color        = 0xee1a1a1a,
        },

        blur             = {
            enabled  = false,
            size     = 8,
            passes   = 3,
            vibrancy = 0.1696,
            variant  = "kawase"
        },
    },

    animations = {
        enabled = true,
    },
})

hl.config({
    windowrule = {
        {
            name = "ghostty-blur",
            match = {
                class = "^(com\\.mitchellh\\.ghostty)$",
            },
            opacity = 0.85,
            blur = true,
        },
    },
})

hl.layer_rule({
    match     = { namespace = "rofi" },
    animation = "popin 85%",   -- or "slide", "fade", etc.
    -- blur = true,           -- optional
})

