---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER"

-- Applications
hl.bind("SUPER + RETURN", hl.dsp.exec_cmd(terminal))

hl.bind("SUPER  + SHIFT + RETURN", hl.dsp.exec_cmd("zen-browser"))


hl.bind("SUPER + CTRL + E", hl.dsp.exec_cmd("rofi -show emoji"))
hl.bind("SUPER + SPACE", hl.dsp.exec_cmd("rofi -show drun"))
-- hl.bind("SUPER + ALT + SPACE", hl.dsp.exec_cmd("wofi --show run"))
-- hl.bind("SUPER + E", hl.dsp.exec_cmd(fileManager))
hl.bind("SUPER + SHIFT + F", hl.dsp.exec_cmd(fileManager))

-- Window management
hl.bind("SUPER + W", hl.dsp.window.close())

hl.bind("SUPER + F", hl.dsp.window.fullscreen())

hl.bind("SUPER + T", hl.dsp.window.float({ action = "toggle" }))
hl.bind("SUPER + P", hl.dsp.window.pseudo())
hl.bind("SUPER + J", hl.dsp.layout("togglesplit"))

-- Focus with arrows
hl.bind("SUPER + LEFT", hl.dsp.focus({ direction = "left" }))
hl.bind("SUPER + RIGHT", hl.dsp.focus({ direction = "right" }))
hl.bind("SUPER + UP", hl.dsp.focus({ direction = "up" }))
hl.bind("SUPER + DOWN", hl.dsp.focus({ direction = "down" }))

hl.bind("SUPER + CTRL + SPACE", hl.dsp.exec_cmd("waypaper"))

-- Move windows with Shift + arrows
hl.bind("SUPER + SHIFT + LEFT",
    hl.dsp.exec_cmd("hyprctl dispatch swapwindow l"))
hl.bind("SUPER + SHIFT + RIGHT",
    hl.dsp.exec_cmd("hyprctl dispatch swapwindow r"))
hl.bind("SUPER + SHIFT + UP",
    hl.dsp.exec_cmd("hyprctl dispatch swapwindow u"))
hl.bind("SUPER + SHIFT + DOWN",
    hl.dsp.exec_cmd("hyprctl dispatch swapwindow d"))

-- Workspaces 1-10
for i = 1, 10 do
    local key = i % 10
    hl.bind("SUPER + " .. key,
        hl.dsp.focus({ workspace = i }))
    hl.bind("SUPER + SHIFT + " .. key,
        hl.dsp.window.move({ workspace = i }))
end

-- Workspace navigation
hl.bind("SUPER + TAB",
    hl.dsp.focus({ workspace = "e+1" }))
hl.bind("SUPER + SHIFT + TAB",
    hl.dsp.focus({ workspace = "e-1" }))

-- Scratchpad
hl.bind("SUPER + S",
    hl.dsp.workspace.toggle_special("magic"))

hl.bind("SUPER + ALT + S",
    hl.dsp.window.move({ workspace = "special:magic" }))

-- Clipboard history
hl.bind("SUPER + V",
    hl.dsp.exec_cmd("rofi -show run"))

-- Screenshots
hl.bind("PRINT",
    hl.dsp.exec_cmd("grim ~/Pictures/screenshot.png"))

-- hl.bind("SUPER + SHIFT + S",
--     hl.dsp.exec_cmd("grim -g \"$(slurp)\" ~/Pictures/screenshot.png"))

-- Lock screen (requires hyprlock)
hl.bind("SUPER + CTRL + L",
    hl.dsp.exec_cmd("hyprlock"))

-- Mouse window manipulation
hl.bind("SUPER + mouse:272",
    hl.dsp.window.drag(), { mouse = true })
hl.bind("SUPER + mouse:273",
    hl.dsp.window.resize(), { mouse = true })

-- Move windows with Super + Shift + arrows
hl.bind("SUPER + SHIFT + LEFT", hl.dsp.window.move({ direction = "left" }))
hl.bind("SUPER + SHIFT + RIGHT", hl.dsp.window.move({ direction = "right" }))
hl.bind("SUPER + SHIFT + UP", hl.dsp.window.move({ direction = "up" }))
hl.bind("SUPER + SHIFT + DOWN", hl.dsp.window.move({ direction = "down" }))

hl.bind("SUPER + COMMA", hl.dsp.exec_cmd("dunstctl close"))
hl.bind("SUPER + SHIFT + COMMA", hl.dsp.exec_cmd("dunstctl close-all"))

-- Window resizing
hl.bind("SUPER + Minus", hl.dsp.window.resize({
    x = -60, y = 0, relative = true
}))

hl.bind("SUPER + Equal", hl.dsp.window.resize({
    x = 60, y = 0, relative = true
}))

hl.bind("SUPER + SHIFT + Minus", hl.dsp.window.resize({
    x = 0, y = -60, relative = true
}))

hl.bind("SUPER + SHIFT + Equal", hl.dsp.window.resize({
    x = 0, y = 60, relative = true
}))

