--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

-- Smart gaps: single-window workspaces
hl.workspace_rule({
    workspace = "w[tv1]",
    gaps_out = { 0, 0, 0, 0 },
    gaps_in = 0,
})

hl.window_rule({
    match = {
        float = false,
        workspace = "w[t1]",
    },
    rounding = 0,
    border_size = 0,
})
